/**
 * Developer-mode only. Fires a synthetic event through each notifier's real onXxx() method, so
 * message formatting/rendering can be checked in Rocket.Chat without grinding up the real game
 * event. Every button still respects that notifier's own config gates (enabled toggle,
 * thresholds, filters) - it exercises the real code path, not a shortcut around it.
 */
public class DebugNotificationPanel extends PluginPanel
{
	private static final int COOLDOWN_MILLIS = 10_000;

	private final ClientThread clientThread;

	public DebugNotificationPanel(
		ClientThread clientThread,
		DeathNotifier deathNotifier,
		LevelNotifier levelNotifier,
		LootNotifier lootNotifier,
		ClueNotifier clueNotifier,
		PetNotifier petNotifier,
		QuestNotifier questNotifier,
		SlayerNotifier slayerNotifier,
		BossNotifier bossNotifier,
		CollectionLogNotifier collectionLogNotifier,
		CombatAchievementNotifier combatAchievementNotifier,
		DiaryNotifier diaryNotifier,
		ChatPatternNotifier chatPatternNotifier,
		GrandExchangeNotifier grandExchangeNotifier)
	{
		this.clientThread = clientThread;

		JLabel header = new JLabel("<html>Fires a test event through each notifier's real "
			+ "code path. Still subject to that notifier's own config (enabled toggle, "
			+ "thresholds, filters) - enable what you want to test first. Each button is "
			+ "limited to once every " + (COOLDOWN_MILLIS / 1000) + "s to avoid hammering your "
			+ "webhook.</html>");
		add(header);

		addButton("Test: Death", deathNotifier::sendTestNotification);
		addButton("Test: Level up", levelNotifier::sendTestNotification);
		addButton("Test: Loot", lootNotifier::sendTestNotification);
		addButton("Test: Clue reward", clueNotifier::sendTestNotification);
		addButton("Test: Pet", petNotifier::sendTestNotification);
		addButton("Test: Quest complete", questNotifier::sendTestNotification);
		addButton("Test: Slayer task", slayerNotifier::sendTestNotification);
		addButton("Test: Boss kill count", bossNotifier::sendTestNotification);
		addButton("Test: Collection log", collectionLogNotifier::sendTestNotification);
		addButton("Test: Combat achievement", combatAchievementNotifier::sendTestNotification);
		addButton("Test: Achievement diary", diaryNotifier::sendTestNotification);
		addButton("Test: Chat pattern", chatPatternNotifier::sendTestNotification);
		addButton("Test: GE trade", grandExchangeNotifier::sendTestNotification);
	}

	private void addButton(String label, Runnable action)
	{
		JButton button = new JButton(label);
		button.addActionListener(e -> fire(button, label, action));
		add(button);
	}

	/**
	 * Each button has its own independent cooldown, so testing several different notifiers back
	 * to back isn't blocked by one shared panel-wide timer - only clicking the *same* button
	 * again within the cooldown window is.
	 */
	private void fire(JButton button, String label, Runnable action)
	{
		// ItemManager/Client calls in the notifiers must run on the client thread, not the
		// Swing EDT this button listener fires on - see AGENTS.md's client-thread rule.
		clientThread.invoke(action);

		button.setEnabled(false);
		button.setText(label + " (cooldown)");

		Timer cooldown = new Timer(COOLDOWN_MILLIS, e ->
		{
			button.setEnabled(true);
			button.setText(label);
		});
		cooldown.setRepeats(false);
		cooldown.start();
	}

	public static BufferedImage createIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setColor(new Color(0xE7, 0x4C, 0x3C));
		g.fillOval(0, 0, 16, 16);
		g.setColor(Color.WHITE);
		g.setFont(g.getFont().deriveFont(Font.BOLD, 10f));
		g.drawString("T", 5, 12);
		g.dispose();
		return icon;
	}
}

package space.covalent.rocketchat.notifiers;

import java.util.Collections;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;
import net.runelite.client.eventbus.Subscribe;
import space.covalent.rocketchat.PlayerNameFormatter;
import space.covalent.rocketchat.RocketChatConnectorConfig;
import space.covalent.rocketchat.RocketChatPayload;
import space.covalent.rocketchat.WebhookClient;

@Singleton
public class BossNotifier
{
	private static final Pattern KILL_COUNT = Pattern.compile(
		"Your (.+) kill count is: ([\\d,]+)\\.");
	private static final Pattern FIGHT_DURATION = Pattern.compile(
		"Fight duration: ([\\d:]+)\\.(?:.* Personal best: ([\\d:]+))?");

	@Inject Client client;
	@Inject RocketChatConnectorConfig config;
	@Inject WebhookClient webhookClient;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.notifyOnBoss()) return;
		if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

		String msg = Text.removeTags(event.getMessage());
		String name = client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null
			? client.getLocalPlayer().getName()
			: "Unknown";
		// Emoji shortcodes never render in the attachment title field (same Rocket.Chat
		// limitation as item icons), so the "name | ..." line lives in text, not title.
		name = PlayerNameFormatter.format(name, config.ironManMode(), config.useEmojiIcons());

		Matcher kc = KILL_COUNT.matcher(msg);
		if (kc.find())
		{
			if (config.bossPersonalBestOnly()) return;
			String boss = kc.group(1);
			String count = kc.group(2);
			int countVal;
			try { countVal = Integer.parseInt(count.replace(",", "")); }
			catch (NumberFormatException e) { return; }

			int interval = config.bossKillCountInterval();
			if (interval == 0) return;
			if (interval > 1 && countVal % interval != 0) return;

			webhookClient.send(config.webhookUrl(), RocketChatPayload.builder()
				.attachments(Collections.singletonList(
					RocketChatPayload.Attachment.builder()
						.title(boss + " kill count: " + count)
						.text(name)
						.color("#C0392B")
						.build()
				))
				.build());
			return;
		}

		Matcher fd = FIGHT_DURATION.matcher(msg);
		if (fd.find())
		{
			String duration = fd.group(1);
			String pb = fd.group(2);
			boolean isNewPb = pb != null && pb.equals(duration);

			if (config.bossPersonalBestOnly() && !isNewPb) return;

			String title = isNewPb
				? "New personal best: " + duration
				: "Fight duration: " + duration;

			webhookClient.send(config.webhookUrl(), RocketChatPayload.builder()
				.attachments(Collections.singletonList(
					RocketChatPayload.Attachment.builder()
						.title(title)
						.text(name)
						.color(isNewPb ? "#F1C40F" : "#95A5A6")
						.build()
				))
				.build());
		}
	}

	/**
	 * Fires a synthetic boss kill-count message through the real onChatMessage path, for the
	 * developer-mode debug panel. Still subject to bossPersonalBestOnly / bossKillCountInterval.
	 */
	public void sendTestNotification()
	{
		onChatMessage(new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "",
			"Your Zulrah kill count is: 42.", "", 0));
	}
}

package space.covalent.rocketchat.notifiers;

import java.util.Collections;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;
import space.covalent.rocketchat.RocketChatConnectorConfig;
import space.covalent.rocketchat.RocketChatPayload;
import space.covalent.rocketchat.WebhookClient;

@Slf4j
@Singleton
public class ChatPatternNotifier
{
	@Inject RocketChatConnectorConfig config;
	@Inject WebhookClient webhookClient;

	private String lastRawPattern = null;
	private Pattern cachedPattern = null;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.notifyOnChatPattern()) return;

		String rawPattern = config.chatPattern();
		if (rawPattern == null || rawPattern.isEmpty()) return;

		if (!rawPattern.equals(lastRawPattern))
		{
			try
			{
				cachedPattern = Pattern.compile(rawPattern, Pattern.CASE_INSENSITIVE);
				lastRawPattern = rawPattern;
			}
			catch (PatternSyntaxException e)
			{
				log.debug("Invalid chat pattern regex: {}", rawPattern);
				cachedPattern = null;
				lastRawPattern = rawPattern;
				return;
			}
		}

		if (cachedPattern == null) return;

		String msg = Text.removeTags(event.getMessage());
		if (!cachedPattern.matcher(msg).find()) return;

		webhookClient.send(config.webhookUrl(), RocketChatPayload.builder()
			.attachments(Collections.singletonList(
				RocketChatPayload.Attachment.builder()
					.title("🔔 Pattern match")
					.text(msg)
					.color("#3498DB")
					.build()
			))
			.build());
	}

	/**
	 * Fires a synthetic chat message through the real onChatMessage path, for the developer-mode
	 * debug panel. Only produces a notification if your configured pattern matches this test
	 * string - it can't guess your regex, so this mainly proves the trigger wiring works.
	 */
	public void sendTestNotification()
	{
		onChatMessage(new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "",
			"Test message for Rocket.Chat Connector pattern matching.", "", 0));
	}
}

